WITH exploded AS (SELECT id, effective_from, currency, EXPLODE_OUTER(tier_limits) AS tier_value FROM price_tiers) SELECT currency, DATE_TRUNC('MONTH', effective_from) AS activity_month, AVG(tier_value) AS avg_tier_value, ROUND(AVG(tier_value), 2) AS avg_tier_value_2, COUNT(CASE WHEN currency = 'EUR' THEN 1 END) AS eur_count, COUNT(*) AS row_count FROM exploded GROUP BY currency, DATE_TRUNC('MONTH', effective_from)
